typedef struct { const char *name; const uint8_t *asc; size_t asc_n; const uint8_t *const *au; const size_t *au_n; size_t frames; unsigned channels; const double (*fp)[2][4]; } Stream;

static uint32_t g_rng = 2463534242u;
static uint32_t rnd(void) { g_rng ^= g_rng << 13; g_rng ^= g_rng >> 17; g_rng ^= g_rng << 5; return g_rng; }
static int near(double a, double b) { return fabs(a - b) <= 1e-5 * (1.0 + fabs(b)); }

/* bit writer for synthetic ASC / access units */
typedef struct { uint8_t b[64]; unsigned n; } Bits;
static void put(Bits *x, unsigned value, unsigned width) { while (width--) { const unsigned bit = (value >> width) & 1u; if ((x->n & 7u) == 0) x->b[x->n >> 3] = 0; if (bit) x->b[x->n >> 3] |= (uint8_t)(0x80u >> (x->n & 7u)); x->n++; } }

static void test_asc(void) {
    SautiAacErAsc a; Bits x;
    CHECK(sauti_aac_er_asc_parse(ld_mono_asc, sizeof ld_mono_asc, &a) == 1 && a.aot == 23 && a.rate_index == 3 && a.channel_config == 1 && !a.frame480 && !a.ld_sbr, "LD mono ASC");
    CHECK(sauti_aac_er_asc_parse(eld_mono_asc, sizeof eld_mono_asc, &a) == 1 && a.aot == 39 && a.rate_index == 3 && a.channel_config == 1 && !a.frame480 && !a.ld_sbr, "ELD mono ASC");
    { static const uint8_t st[] = { 0xb9, 0x91, 0x00 }; CHECK(sauti_aac_er_asc_parse(st, sizeof st, &a) == 1 && a.channel_config == 2, "LD stereo ASC"); }
    CHECK(sauti_aac_er_asc_parse(ld_mono_asc, 1, &a) == 0 && sauti_aac_er_asc_parse(ld_mono_asc, 2, &a) == 0 && sauti_aac_er_asc_parse(NULL, 3, &a) == 0 && sauti_aac_er_asc_parse(ld_mono_asc, 0, &a) == 0, "short / NULL ASC");
    /* 480-line LD (frameLengthFlag 1), LD with resilience flags / epConfig / core coder / PCE / explicit frequency / ELD resilience flags / ELD with SBR */
    memset(&x, 0, sizeof x); put(&x, 23, 5); put(&x, 4, 4); put(&x, 2, 4); put(&x, 1, 1); put(&x, 0, 1); put(&x, 0, 1); put(&x, 0, 2);
    CHECK(sauti_aac_er_asc_parse(x.b, (x.n + 7) / 8, &a) == 1 && a.frame480 == 1 && a.rate_index == 4, "LD 480");
    memset(&x, 0, sizeof x); put(&x, 23, 5); put(&x, 3, 4); put(&x, 2, 4); put(&x, 0, 1); put(&x, 0, 1); put(&x, 1, 1); put(&x, 1, 3); put(&x, 0, 1); put(&x, 0, 2);
    CHECK(sauti_aac_er_asc_parse(x.b, (x.n + 7) / 8, &a) == -1, "LD with resilience flags is unsupported");
    memset(&x, 0, sizeof x); put(&x, 23, 5); put(&x, 3, 4); put(&x, 2, 4); put(&x, 0, 1); put(&x, 0, 1); put(&x, 0, 1); put(&x, 1, 2);
    CHECK(sauti_aac_er_asc_parse(x.b, (x.n + 7) / 8, &a) == -1, "epConfig 1 is unsupported");
    memset(&x, 0, sizeof x); put(&x, 23, 5); put(&x, 3, 4); put(&x, 2, 4); put(&x, 0, 1); put(&x, 1, 1); put(&x, 0, 14); put(&x, 0, 1); put(&x, 0, 3); put(&x, 0, 1); put(&x, 0, 2);
    CHECK(sauti_aac_er_asc_parse(x.b, (x.n + 7) / 8, &a) == -1, "dependsOnCoreCoder is unsupported");
    memset(&x, 0, sizeof x); put(&x, 23, 5); put(&x, 3, 4); put(&x, 0, 4); put(&x, 0, 3); put(&x, 0, 4);
    CHECK(sauti_aac_er_asc_parse(x.b, (x.n + 7) / 8, &a) == -1, "channel_configuration 0 (PCE) is unsupported");
    memset(&x, 0, sizeof x); put(&x, 23, 5); put(&x, 15, 4); put(&x, 48000, 24); put(&x, 2, 4); put(&x, 0, 8);
    CHECK(sauti_aac_er_asc_parse(x.b, (x.n + 7) / 8, &a) == -1, "explicit sampling frequency is unsupported");
    memset(&x, 0, sizeof x); put(&x, 2, 5); put(&x, 3, 4); put(&x, 2, 4); put(&x, 0, 8);
    CHECK(sauti_aac_er_asc_parse(x.b, (x.n + 7) / 8, &a) == -1, "AAC-LC is not an ER configuration");
    memset(&x, 0, sizeof x); put(&x, 31, 5); put(&x, 7, 6); put(&x, 3, 4); put(&x, 2, 4); put(&x, 0, 1); put(&x, 1, 1); put(&x, 0, 3); put(&x, 0, 1); put(&x, 0, 8);
    CHECK(sauti_aac_er_asc_parse(x.b, (x.n + 7) / 8, &a) == -1, "ELD with a resilience flag is unsupported");
    memset(&x, 0, sizeof x); put(&x, 31, 5); put(&x, 7, 6); put(&x, 3, 4); put(&x, 2, 4); put(&x, 0, 1); put(&x, 0, 1); put(&x, 0, 1); put(&x, 1, 1); put(&x, 0, 8);
    CHECK(sauti_aac_er_asc_parse(x.b, (x.n + 7) / 8, &a) == -1, "ELD with the spectral-data resilience flag is unsupported");
    memset(&x, 0, sizeof x); put(&x, 31, 5); put(&x, 7, 6); put(&x, 3, 4); put(&x, 2, 4); put(&x, 0, 4); put(&x, 1, 1); put(&x, 1, 1); put(&x, 1, 1); put(&x, 0, 16);
    CHECK(sauti_aac_er_asc_parse(x.b, (x.n + 7) / 8, &a) == 1 && a.ld_sbr == 1 && a.ld_sbr_downsampled == 1 && a.ld_sbr_crc == 1, "ELD with the low-delay SBR flag is reported");
    memset(&x, 0, sizeof x); put(&x, 31, 5); put(&x, 7, 6); put(&x, 3, 4); put(&x, 2, 4); put(&x, 0, 4); put(&x, 0, 1); put(&x, 2, 4); put(&x, 1, 4); put(&x, 0xab, 8); put(&x, 0, 4); put(&x, 0, 2);
    CHECK(sauti_aac_er_asc_parse(x.b, (x.n + 7) / 8, &a) == 1 && a.aot == 39, "ELD extension with a payload is skipped");
    { SautiAacErConfig c = { 23, 3, 0, 1 };
      CHECK(sauti_aac_er_frame_samples(&c) == 512, "LD 512 samples"); c.frame480 = 1; CHECK(sauti_aac_er_frame_samples(&c) == 480, "LD 480 samples");
      c.frame480 = 0; c.aot = 2; CHECK(sauti_aac_er_frame_samples(&c) == 0, "AOT 2"); c.aot = 39; c.rate_index = 2; CHECK(sauti_aac_er_frame_samples(&c) == 0, "64 kHz");
      c.rate_index = 8; CHECK(sauti_aac_er_frame_samples(&c) == 0, "16 kHz"); c.rate_index = 3; c.channel_config = 0; CHECK(sauti_aac_er_frame_samples(&c) == 0, "0 channels");
      c.channel_config = 3; CHECK(sauti_aac_er_frame_samples(&c) == 0, "3 channels (not supported yet)"); c.channel_config = 1; c.frame480 = 2; CHECK(sauti_aac_er_frame_samples(&c) == 0, "frame480 2");
      CHECK(sauti_aac_er_frame_samples(NULL) == 0, "NULL config"); }
}

static void fingerprint(const float *pcm, unsigned n, unsigned ch, double out[2][4]) {            /* sum, sum of squares, position-weighted sum, energy of the second difference (high frequencies) */
    unsigned c, i;
    for (c = 0; c < ch; c++) {
        double s1 = 0, s2 = 0, s3 = 0, s4 = 0;
        for (i = 0; i < n; i++) { const double v = (double)pcm[i * ch + c]; s1 += v; s2 += v * v; s3 += v * (double)(i + 1) / (double)n; if (i >= 2) { const double d = v - 2.0 * (double)pcm[(i - 1) * ch + c] + (double)pcm[(i - 2) * ch + c]; s4 += d * d; } }
        out[c][0] = s1; out[c][1] = s2; out[c][2] = s3; out[c][3] = s4;
    }
}
static void test_stream(const Stream *s) {
    SautiAacErAsc a; SautiAacErConfig cfg; SautiAacErState st; float pcm[1024]; size_t f; SautiAacReason why;
    CHECK(sauti_aac_er_asc_parse(s->asc, s->asc_n, &a) == 1, "%s: ASC", s->name);
    cfg.aot = a.aot; cfg.rate_index = a.rate_index; cfg.frame480 = a.frame480; cfg.channel_config = a.channel_config;
    sauti_aac_er_state_init(&st);
    for (f = 0; f < s->frames; f++) {
        double fp[2][4]; unsigned c, k;
        CHECK(sauti_aac_er_decode(&cfg, &st, s->au[f], s->au_n[f], pcm, &why) == 1, "%s frame %zu: decode (%s)", s->name, f, sauti_aac_reason_name(why));
        fingerprint(pcm, 512, s->channels, fp);
        for (c = 0; c < s->channels; c++) for (k = 0; k < 4; k++) CHECK(near(fp[c][k], s->fp[f][c][k]), "%s frame %zu ch %u fingerprint %u: %.12e vs %.12e", s->name, f, c, k, fp[c][k], s->fp[f][c][k]);
    }
}

/* atomic on failure: state and output unchanged, whatever the input */
static void test_atomic(const Stream *s) {
    SautiAacErAsc a; SautiAacErConfig cfg; SautiAacErState st, before; float pcm[1024], keep[1024]; SautiAacReason why; size_t f, len, i; int round; long accepted = 0, rejected = 0;
    sauti_aac_er_asc_parse(s->asc, s->asc_n, &a);
    cfg.aot = a.aot; cfg.rate_index = a.rate_index; cfg.frame480 = a.frame480; cfg.channel_config = a.channel_config;
    sauti_aac_er_state_init(&st);
    for (i = 0; i < 1024; i++) keep[i] = pcm[i] = 12345.0f;
    for (f = 0; f < s->frames; f++) {
        for (len = 0; len <= s->au_n[f]; len++) {                                                           /* every truncation */
            int r; before = st; memcpy(pcm, keep, sizeof pcm);
            r = sauti_aac_er_decode(&cfg, &st, s->au[f], len, pcm, &why);
            if (r != 1) { CHECK(memcmp(&before, &st, sizeof st) == 0 && memcmp(pcm, keep, sizeof pcm) == 0, "%s frame %zu len %zu: failure (%d) must leave state and output alone", s->name, f, len, r); rejected++; }
            else { for (i = 0; i < 512u * s->channels; i++) CHECK(isfinite(pcm[i]), "%s: non-finite output", s->name); st = before; accepted++; }
        }
        for (round = 0; round < 400; round++) {                                                             /* random bit flips */
            uint8_t au[1024]; int r, nflip = 1 + (int)(rnd() % 4u);
            memcpy(au, s->au[f], s->au_n[f]);
            while (nflip--) { const size_t at = rnd() % s->au_n[f]; au[at] ^= (uint8_t)(1u << (rnd() & 7u)); }
            before = st; memcpy(pcm, keep, sizeof pcm);
            r = sauti_aac_er_decode(&cfg, &st, au, s->au_n[f], pcm, &why);
            if (r != 1) { CHECK(memcmp(&before, &st, sizeof st) == 0 && memcmp(pcm, keep, sizeof pcm) == 0, "%s frame %zu flip: failure (%d) must leave state and output alone", s->name, f, r); rejected++; }
            else { for (i = 0; i < 512u * s->channels; i++) CHECK(isfinite(pcm[i]), "%s: non-finite output after flips", s->name); st = before; accepted++; }
        }
    }
    printf("%s: %ld accepted, %ld rejected mutated or truncated access units\n", s->name, accepted, rejected);
    CHECK(rejected > 100, "%s: mutations never fail?", s->name);
}


/* hand-built access units: silent frames and the syntax checks that real streams do not exercise (window sequence, max_sfb limits per layout, gain control, intensity, Mid/Side mask) */
static void zero_sections(Bits *x, unsigned bands) {                                                  /* one section of the zero codebook covering `bands` scalefactor bands */
    unsigned rem = bands; if (!bands) return;
    put(x, 0, 4);
    while (rem >= 31u) { put(x, 31, 5); rem -= 31u; }
    put(x, rem, 5);
}
static void one_section(Bits *x, unsigned codebook, unsigned bands) { put(x, codebook, 4); put(x, bands, 5); }
static void ld_ics(Bits *x, unsigned max_sfb) { put(x, 0, 1); put(x, 0, 2); put(x, 0, 1); put(x, max_sfb, 6); put(x, 0, 1); }       /* reserved, ONLY_LONG, sine window, max_sfb, no predictor */
static int run(unsigned aot, unsigned rate, unsigned frame480, unsigned channels, const Bits *x, float *pcm, SautiAacReason *why) {
    SautiAacErConfig cfg; SautiAacErState st; cfg.aot = aot; cfg.rate_index = rate; cfg.frame480 = frame480; cfg.channel_config = channels;
    sauti_aac_er_state_init(&st);
    return sauti_aac_er_decode(&cfg, &st, x->b, (x->n + 7) / 8 + 4, pcm, why);                          /* a few spare zero bytes: a truncated header must not be what fails */
}
static int silent(const float *pcm, size_t n) { size_t i; for (i = 0; i < n; i++) if (pcm[i] != 0.0f) return 0; return 1; }
static void test_crafted(void) {
    float pcm[1024]; SautiAacReason why; Bits x; unsigned n;
    /* silent frames: AAC-LD and AAC-ELD, 512 and 480 lines, mono and stereo */
    for (n = 0; n < 8; n++) {
        const unsigned aot = (n & 1) ? 39u : 23u, f480 = (n >> 1) & 1u, ch = (n >> 2) + 1u; const unsigned lines = f480 ? 480u : 512u; int r;
        memset(&x, 0, sizeof x); memset(pcm, 0x55, sizeof pcm);
        if (ch == 1) { if (aot == 23u) put(&x, 0, 4); put(&x, 100, 8); if (aot == 23u) ld_ics(&x, 0); else put(&x, 0, 6); if (aot == 23u) { put(&x, 0, 1); put(&x, 0, 1); put(&x, 0, 1); } else put(&x, 0, 1); }
        else {
            if (aot == 23u) { put(&x, 0, 4); put(&x, 1, 1); ld_ics(&x, 0); } else put(&x, 0, 6);
            put(&x, 0, 2);
            { unsigned c; for (c = 0; c < 2; c++) { put(&x, 100, 8); if (aot == 23u) { put(&x, 0, 1); put(&x, 0, 1); put(&x, 0, 1); } else put(&x, 0, 1); } }
        }
        r = run(aot, 3, f480, ch, &x, pcm, &why);
        CHECK(r == 1 && silent(pcm, (size_t)lines * ch), "silent frame aot %u lines %u channels %u: %d (%s)", aot, lines, ch, r, sauti_aac_reason_name(why));
    }
    /* band count limits follow the layout: 36 bands at 48 kHz for 512 lines, 35 for 480 */
    { unsigned m; for (m = 35; m <= 37; m++) {
        int r512, r480; memset(&x, 0, sizeof x); put(&x, 0, 4); put(&x, 100, 8); ld_ics(&x, m); zero_sections(&x, m); put(&x, 0, 3);
        r512 = run(23, 3, 0, 1, &x, pcm, &why); r480 = run(23, 3, 1, 1, &x, pcm, &why);
        CHECK(r512 == (m <= 36 ? 1 : 0) && r480 == (m <= 35 ? 1 : 0), "max_sfb %u: 512 lines -> %d, 480 lines -> %d", m, r512, r480); } }
    { int r; memset(&x, 0, sizeof x); put(&x, 0, 4); put(&x, 100, 8); ld_ics(&x, 63); zero_sections(&x, 63); put(&x, 0, 3); r = run(23, 3, 0, 1, &x, pcm, &why); CHECK(r == 0, "max_sfb 63 must be rejected (%d)", r); }
    /* short windows do not exist in AAC-LD */
    { int r; memset(&x, 0, sizeof x); put(&x, 0, 4); put(&x, 100, 8); put(&x, 0, 1); put(&x, 2, 2); put(&x, 0, 1); put(&x, 0, 4); put(&x, 0, 7); put(&x, 0, 3); r = run(23, 3, 0, 1, &x, pcm, &why); CHECK(r == 0, "EIGHT_SHORT_SEQUENCE in AAC-LD must be rejected (%d)", r); }
    /* gain control (SSR tool) is unsupported, intensity stereo only in the right channel of a common_window pair */
    { int r; memset(&x, 0, sizeof x); put(&x, 0, 4); put(&x, 100, 8); ld_ics(&x, 0); put(&x, 0, 2); put(&x, 1, 1); r = run(23, 3, 0, 1, &x, pcm, &why); CHECK(r == -1 && why == SAUTI_AAC_REASON_GAIN_CONTROL, "gain control must be -1 (%d)", r); }
    { int r; memset(&x, 0, sizeof x); put(&x, 0, 4); put(&x, 100, 8); ld_ics(&x, 1); one_section(&x, 15, 1); put(&x, 0, 1); put(&x, 0, 3); r = run(23, 3, 0, 1, &x, pcm, &why); CHECK(r == -1, "intensity in a mono element must be -1 (%d)", r); }
    for (n = 0; n < 2; n++) {                                                                           /* CPE: right-channel intensity is fine (n = 0 AAC-LD, 1 AAC-ELD); MS mask 3 is reserved */
        const unsigned aot = n ? 39u : 23u; int r; unsigned mask;
        for (mask = 0; mask < 4; mask += 3) {
            memset(&x, 0, sizeof x);
            if (aot == 23u) { put(&x, 0, 4); put(&x, 1, 1); ld_ics(&x, 1); } else put(&x, 1, 6);
            put(&x, mask, 2);
            put(&x, 100, 8); one_section(&x, 0, 1); if (aot == 23u) { put(&x, 0, 1); put(&x, 0, 1); put(&x, 0, 1); } else put(&x, 0, 1);
            put(&x, 100, 8); one_section(&x, 15, 1); put(&x, 0, 1); if (aot == 23u) { put(&x, 0, 1); put(&x, 0, 1); put(&x, 0, 1); } else put(&x, 0, 1);
            memset(pcm, 0x55, sizeof pcm); r = run(aot, 3, 0, 2, &x, pcm, &why);
            if (mask == 0) CHECK(r == 1 && silent(pcm, 1024), "aot %u: intensity band in the right channel: %d (%s)", aot, r, sauti_aac_reason_name(why));
            else CHECK(r == 0, "aot %u: ms_mask_present 3 is reserved: %d", aot, r);
        }
    }
}

/* AAC-LD synthesis against an independent direct implementation: IMDCT by the cosine sum, the two window shapes written out from their definitions, overlap-add of the halves */
static void ref_imdct(const float *x, unsigned n, double *y) {
    const double pi = 3.14159265358979323846264338327950288;
    unsigned t, k;
    for (t = 0; t < 2u * n; t++) { double acc = 0; for (k = 0; k < n; k++) acc += (double)x[k] * cos(pi / (double)n * ((double)t + 0.5 + (double)n / 2.0) * ((double)k + 0.5)); y[t] = acc * 2.0 / (double)n; }
}
static double ref_window(unsigned n, unsigned shape, unsigned i) {
    const double pi = 3.14159265358979323846264338327950288;
    if (i >= n) i = 2u * n - 1u - i;
    if (shape == 0u) return sin(pi * ((double)i + 0.5) / (2.0 * (double)n));
    if (i < 192u) return 0.0;
    if (i < 320u) return sin(pi * ((double)(i - 192u) + 0.5) / 256.0);
    return 1.0;
}
static void test_ld_window(void) {
    unsigned n, shape, frame, i, k;
    for (n = 480; n <= 512; n += 32) for (shape = 0; shape < 2; shape++) {
        SautiAacErChannel ch; double prev[512] = { 0 }; int ok = 1;
        memset(&ch, 0, sizeof ch);
        if (n == 480 && shape == 1) { float sp[1024] = { 0 }, out[512]; CHECK(!ld_synthesis(&ch, n, shape, sp, out), "the low-overlap window is defined for 512 lines only"); continue; }
        for (frame = 0; frame < 4 && ok; frame++) {
            float sp[1024] = { 0 }, out[512]; double y[1024];
            for (k = 0; k < n; k++) sp[k] = (float)((int)(rnd() % 2001u) - 1000) / 40.0f;
            ref_imdct(sp, n, y);
            CHECK(ld_synthesis(&ch, n, shape, sp, out) == 1, "n=%u shape=%u frame %u", n, shape, frame);
            for (i = 0; i < n; i++) {
                const double want = prev[i] + y[i] * ref_window(n, shape, i);
                if (fabs((double)out[i] - want) > 1e-3 + 1e-5 * fabs(want)) { CHECK(0, "n=%u shape=%u frame %u sample %u: %g vs %g", n, shape, frame, i, (double)out[i], want); ok = 0; break; }
                prev[i] = y[n + i] * ref_window(n, shape, n + i);
            }
        }
    }
}

